using System;using System.IO;using ScoreModern.RecoveredFragments;
class InputBeamFitProof{
 static int Main(string[] a){try{byte[] ds=File.ReadAllBytes(a[0]),common=File.ReadAllBytes(a[1]),pref=File.ReadAllBytes(a[2]),after=File.ReadAllBytes(a[3]);int count=BitConverter.ToInt16(ds,0x815e);float[] y=new float[count],x=new float[count];for(int i=0;i<count;i++){y[i]=BitConverter.ToSingle(common,0x2e18+i*4);int item=BitConverter.ToInt16(common,0x2fa8+i*2);x[i]=BitConverter.ToSingle(common,(item-1)*60+8);}var r=InputBeamFit.Fit(y,x,BitConverter.ToInt16(ds,0x8600),BitConverter.ToInt16(ds,0x815a),BitConverter.ToSingle(pref,0));float[] actual={r.Start,r.End,r.UnquantizedStart,r.UnquantizedEnd};int[] offsets={0x813c,0x8140,0xd620,0xd624};for(int i=0;i<offsets.Length;i++)if(BitConverter.ToUInt32(BitConverter.GetBytes(actual[i]),0)!=BitConverter.ToUInt32(after,offsets[i]))throw new Exception(offsets[i].ToString("x4")+": "+actual[i]+" != "+BitConverter.ToSingle(after,offsets[i]));if(r.Direction!=BitConverter.ToInt16(after,0x8600))throw new Exception("Direction");Console.WriteLine("PASS original beam fit: four float values and direction");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
